import json
import re
import unittest

from ledgerlock.format import GENESIS, canonical_bytes, line_hash


class TestCanonicalBytes(unittest.TestCase):
    def test_AC_STORY_01_02_1_matches_json_dumps_default(self) -> None:
        line = {"key": "value", "rid": "abc"}
        expected = json.dumps(
            line, sort_keys=True, separators=(",", ":"), ensure_ascii=False
        ).encode("utf-8")
        self.assertEqual(canonical_bytes(line), expected)

    def test_AC_STORY_01_02_1_returns_bytes_when_hash_and_prev_hash_unset(self) -> None:
        line = {"key": "value", "rid": "abc"}
        result = canonical_bytes(line)
        self.assertIsInstance(result, bytes)
        expected = json.dumps(
            line, sort_keys=True, separators=(",", ":"), ensure_ascii=False
        ).encode("utf-8")
        self.assertEqual(result, expected)

    def test_AC_STORY_01_02_2_equal_dicts_produce_identical_bytes(self) -> None:
        first = {"rid": "r", "key": "k", "op": "put"}
        second = dict(first)
        self.assertEqual(canonical_bytes(first), canonical_bytes(second))

    def test_AC_STORY_01_02_3_non_ascii_uses_utf8_literal(self) -> None:
        line = {"name": "\u00e9"}
        result = canonical_bytes(line)
        self.assertEqual(result, b'{"name":"\xc3\xa9"}')

    def test_AC_STORY_01_02_3_byte_stable_across_invocations(self) -> None:
        line = {"name": "\u00e9", "city": "Qu\u00e9bec"}
        first = canonical_bytes(line)
        second = canonical_bytes(line)
        self.assertEqual(first, second)

    def test_AC_STORY_01_02_4_key_order_does_not_affect_bytes(self) -> None:
        first = {"a": 1, "b": 2, "c": 3}
        second = {"c": 3, "b": 2, "a": 1}
        self.assertEqual(canonical_bytes(first), canonical_bytes(second))

    def test_AC_STORY_01_02_6_round_trip_through_json_loads(self) -> None:
        original = {"rid": "r", "key": "k", "value": 42, "tag": "\u00e9"}
        first = canonical_bytes(original)
        round_tripped = json.loads(first.decode("utf-8"))
        second = canonical_bytes(round_tripped)
        self.assertEqual(first, second)


class TestGenesis(unittest.TestCase):
    def test_AC_STORY_01_02_5_genesis_is_seven_char_literal(self) -> None:
        self.assertEqual(GENESIS, "GENESIS")

    def test_AC_STORY_01_02_5_genesis_not_a_64_char_hex(self) -> None:
        self.assertNotEqual(len(GENESIS), 64)


class TestLineHash(unittest.TestCase):
    HEX64 = re.compile(r"^[0-9a-f]{64}$")

    def test_AC_STORY_01_03_1_returns_64_lowercase_hex_chars(self) -> None:
        line = {"rid": "r", "key": "k", "op": "put", "value": 1}
        result = line_hash("GENESIS", line)
        self.assertIsInstance(result, str)
        self.assertEqual(len(result), 64)
        self.assertRegex(result, self.HEX64)

    def test_AC_STORY_01_03_2_distinct_prev_hash_yields_distinct_digest(self) -> None:
        line = {"rid": "r", "key": "k", "op": "put", "value": 1}
        first = line_hash("a" * 64, line)
        second = line_hash("b" * 64, line)
        self.assertNotEqual(first, second)

    def test_AC_STORY_01_03_3_ignores_hash_and_prev_hash_on_input(self) -> None:
        clean = {"rid": "r", "key": "k", "op": "put", "value": 1}
        dirty = {"rid": "r", "key": "k", "op": "put", "value": 1,
                 "prev_hash": "ignored", "hash": "also_ignored"}
        self.assertEqual(line_hash("GENESIS", clean), line_hash("GENESIS", dirty))
        self.assertEqual(clean, clean)

    def test_AC_STORY_01_03_4_deterministic_across_invocations(self) -> None:
        line = {"rid": "r", "key": "k", "op": "put", "value": 1}
        first = line_hash("GENESIS", line)
        second = line_hash("GENESIS", line)
        self.assertEqual(first, second)

    def test_AC_STORY_01_03_5_accepts_genesis_literal(self) -> None:
        line = {"rid": "r", "key": "k", "op": "put", "value": 1}
        result = line_hash("GENESIS", line)
        self.assertEqual(len(result), 64)
        self.assertRegex(result, self.HEX64)


if __name__ == "__main__":
    unittest.main()

